// Settings
const WINDOW_MIN = 3;   // max minutes between uploads in the same batch
const now = Date.now();
const PENDING = ['received', 'analyzing', 'analyzed'];

// 1. Takes not yet through selection, oldest first
const rows = $input.all()
  .map(item => item.json)
  .filter(r => PENDING.includes(r.status))
  .sort((a, b) => new Date(a.received_at) - new Date(b.received_at));

// 2. Group into batches: a gap longer than the window starts a new batch
const batches = [];
for (const row of rows) {
  const t = new Date(row.received_at).getTime();
  const current = batches[batches.length - 1];
  if (current && t - current.lastTime <= WINDOW_MIN * 60000) {
    current.rows.push(row);
    current.lastTime = t;
  } else {
    batches.push({ id: 'batch_' + row.received_at, rows: [row], lastTime: t });
  }
}

// 3. Pick a winner in each settled batch
const updates = [];
for (const b of batches) {
  const settled = now - b.lastTime > WINDOW_MIN * 60000;
  const allAnalyzed = b.rows.every(r => r.status === 'analyzed');
  if (!settled || !allAnalyzed) continue; // takes still arriving or being analyzed

  const scored = b.rows.map(r => {
    let a = {};
    try { a = JSON.parse(r.segments); } catch (e) {}
    const segs = (a.usable && Array.isArray(a.segments)) ? a.segments : [];
    let best = null;
    for (const s of segs) {
      if (!best || s.score > best.score ||
          (s.score === best.score && s.hook_candidate && !best.hook_candidate)) best = s;
    }
    return { row: r, score: best ? best.score : -1, hook: best ? best.hook_candidate === true : false };
  });

  scored.sort((x, y) => (y.score - x.score) || (y.hook - x.hook));
  const winner = scored[0];

  for (const s of scored) {
    let status;
    if (s.score < 0) status = 'no_usable_footage';
    else if (s === winner) status = 'selected';
    else status = 'alternate_take';
    updates.push({ json: { file_id: s.row.file_id, batch_id: b.id, status } });
  }
}

return updates;

const row = $('Get approved status').first().json;
const s = $('Publish Settings').first().json;
const media = s.media_url;
const tags = row.hashtags ? '\n\n' + row.hashtags : '';

const posts = [
  { platform: 'instagram', body: { post: {
      accountId: s.ig_account_id,
      content: { text: row.caption_ig + tags, mediaUrls: [media], platform: 'instagram' },
      target: { targetType: 'instagram', mediaType: 'reel' } } } },

  { platform: 'facebook', body: { post: {
      accountId: s.fb_account_id,
      content: { text: row.caption_fb + tags, mediaUrls: [media], platform: 'facebook' },
      target: { targetType: 'facebook', pageId: s.fb_page_id, mediaType: 'reel' } } } },

  { platform: 'tiktok', body: { post: {
      accountId: s.tt_account_id,
      content: { text: row.caption_tt + tags, mediaUrls: [media], platform: 'tiktok' },
      target: { targetType: 'tiktok', privacyLevel: s.tt_privacy,
        disabledComments: false, disabledDuet: false, disabledStitch: false,
        isBrandedContent: s.tt_is_branded_content, isYourBrand: s.tt_is_your_brand,
        isAiGenerated: s.tt_ai_generated } } } },

  { platform: 'youtube', body: { post: {
      accountId: s.yt_account_id,
      content: { text: row.caption_ig + tags, mediaUrls: [media], platform: 'youtube' },
      target: { targetType: 'youtube', title: row.yt_title, privacyStatus: s.yt_privacy,
        shouldNotifySubscribers: false } } } },
];

return posts.map(p => ({
  json: { file_id: row.file_id, platform: p.platform, dry_run: s.dry_run, body: p.body }
}));
